'use strict';
(()=>{
const byId=id=>document.getElementById(id);let account=null,mode='all',offset=0,listVersion=0,threadVersion=0,currentThread=null,replyOffset=0,saving=false,loginAvailable=false;
const access=new URLSearchParams(location.search).get('acceso');const accessNotice=access==='limite'?'Espera unos minutos antes de volver a iniciar sesión.':access==='pendiente'?'El acceso con Google está pendiente de configuración.':access?'No se pudo completar el acceso. Puedes intentarlo de nuevo.':'';
function resetSession(){account=null;mode='all';offset=0;replyOffset=0;currentThread=null;listVersion++;threadVersion++;byId('account').hidden=true;byId('google-login').hidden=!loginAvailable;byId('compose').hidden=true;byId('my-topics').hidden=true;byId('moderation').hidden=true;byId('link-owner').hidden=true;byId('owner-note').hidden=true;byId('reply-form').hidden=true;byId('more-topics').hidden=true;byId('more-topics').disabled=false;byId('more-replies').hidden=true;byId('more-replies').disabled=false;byId('topics').replaceChildren();byId('thread-content').replaceChildren();byId('thread-replies').replaceChildren();byId('topics').setAttribute('aria-busy','false');for(const id of ['all-topics','my-topics','moderation'])byId(id).setAttribute('aria-pressed',String(id==='all-topics'));notice('thread-title','Sesión terminada');notice('reply-status','Conecta con Google para participar.');notice('login-note',loginAvailable?'Tu sesión ha terminado. Conecta con Google para participar.':'Tu sesión ha terminado. El acceso con Google no está disponible ahora.');notice('community-status','Tu sesión ha terminado. Puedes seguir leyendo las conversaciones públicas.');}
async function api(path,body){const response=await fetch('/api/community/'+path,{credentials:'same-origin',cache:'no-store',...(body!==undefined?{method:'POST',headers:{'Content-Type':'application/json','X-Community-Action':'write'},body:JSON.stringify(body)}:{})});let data;try{data=await response.json();}catch{throw Error('No se ha podido conectar. Inténtalo de nuevo.');}if(!response.ok){if(response.status===401)resetSession();throw Error(data.error||'No se ha podido completar la acción.');}return data;}
function text(tag,value,className){const el=document.createElement(tag);el.textContent=value;if(className)el.className=className;return el;}
function button(label,action){const el=text('button',label,'text-button');el.type='button';el.addEventListener('click',action);return el;}
function notice(id,value){byId(id).textContent=value;}
function locked(value){saving=value;for(const id of ['topic-form','reply-form','profile-form'])for(const el of byId(id).elements)el.disabled=value;}
function postElement(post,{preview=false,moderate=false}={}){
 const article=document.createElement('article');article.className='topic';const meta=document.createElement('div');meta.className='topic-meta';meta.append(text('span',post.author),text('span',post.role==='owner'?'Dueño':'Lector','rank '+(post.role==='owner'?'owner':'')),text('time',new Intl.DateTimeFormat('es-ES',{dateStyle:'medium',timeStyle:'short'}).format(new Date(post.createdAt))));article.append(meta);
 if(post.status!=='published')article.append(text('p',post.status==='pending'?'Pendiente de revisión':'Retirada','rank'));
 if(post.title){const heading=document.createElement('h3');if(preview&&post.status!=='hidden'){const open=button(post.title,()=>openThread(post.id));open.className='topic-open';heading.append(open);}else heading.textContent=post.title;article.append(heading);}
 article.append(text('p',preview&&post.body.length>240?post.body.slice(0,240)+'…':post.body,'topic-body'));
 const actions=document.createElement('div');actions.className='topic-actions';
 if(post.mine&&post.status!=='hidden')actions.append(button('Retirar mi publicación',async()=>{if(saving||!confirm('¿Retirar esta publicación? Si inicia una conversación, también dejarán de verse sus respuestas.'))return;locked(true);try{await api('posts/'+post.id+'/delete',{version:post.version});byId('thread-dialog').close();await loadTopics();}catch(e){notice('community-status',e.message);notice('reply-status',e.message);}finally{locked(false);}}));
 if(moderate){const reason=document.createElement('input');reason.maxLength=500;reason.placeholder='Motivo si retiras el contenido';reason.setAttribute('aria-label','Motivo de moderación');actions.append(reason);for(const [label,status]of [['Publicar','published'],['Retirar','hidden']])actions.append(button(label,async()=>{if(saving)return;locked(true);try{await api('posts/'+post.id+'/moderate',{version:post.version,status,reason:reason.value});await loadTopics();}catch(e){notice('community-status',e.message);}finally{locked(false);}}));}
 if(post.status==='published'){const report=document.createElement('a');report.href='mailto:theshoz@gmail.com?subject='+encodeURIComponent('Aviso sobre publicación '+post.id);report.textContent='Avisar de un problema';report.className='text-button';actions.append(report);}article.append(actions);return article;
}
async function loadAccount(){
 const result=await api('me');account=result.user;loginAvailable=result.loginAvailable;byId('google-login').hidden=!!account||!loginAvailable;byId('account').hidden=!account;
 notice('login-note',account?'Tu correo es privado. Solo se muestra el nombre público que elijas.':result.loginAvailable?'Puedes leer sin cuenta. Conecta con Google para participar.':'Estamos preparando el acceso con Google. La comunidad todavía no admite publicaciones.');
 byId('compose').hidden=!account?.accepted_at;byId('my-topics').hidden=!account;byId('moderation').hidden=account?.role!=='owner';byId('link-owner').hidden=!result.canLinkOwner||account?.role==='owner';byId('owner-note').hidden=byId('link-owner').hidden;
 if(account){notice('profile-name',account.alias);notice('profile-role',account.role==='owner'?'Dueño':'Lector');byId('profile-role').className='rank '+(account.role==='owner'?'owner':'');byId('alias').value=account.alias;byId('accept-rules').checked=!!account.accepted_at;}
}
async function loadTopics(append=false){if(append&&byId('more-topics').disabled)return;const version=++listVersion,requestedOffset=append?offset+20:0;byId('topics').setAttribute('aria-busy','true');byId('more-topics').disabled=true;notice('community-status',accessNotice||'Cargando conversaciones…');try{
 const path=mode==='moderation'?'moderation':'posts?offset='+requestedOffset+(mode==='mine'?'&mine=1':'');const result=await api(path);if(version!==listVersion)return;offset=requestedOffset;
 if(!append)byId('topics').replaceChildren();for(const post of result.posts)byId('topics').append(postElement(post,{preview:mode!=='moderation',moderate:mode==='moderation'}));
 if(!offset&&!result.posts.length){const empty=document.createElement('div');empty.className='community-empty';empty.append(text('h3',mode==='moderation'?'No hay aportaciones pendientes.':mode==='mine'?'Todavía no has abierto una conversación.':'Una primera pregunta puede abrir el camino.'),text('p',mode==='all'?'Cuando la comunidad esté activa, aquí aparecerán las preguntas y respuestas aprobadas.':'Las publicaciones se mostrarán aquí cuando estén disponibles.'));byId('topics').append(empty);}
 byId('more-topics').hidden=!result.hasMore;notice('community-status',accessNotice);
 }catch(e){if(version===listVersion)notice('community-status',(accessNotice?accessNotice+' ':'')+e.message+(append?' Pulsa Más conversaciones para reintentar.':' Usa Actualizar para reintentar.'));}finally{if(version===listVersion){byId('topics').setAttribute('aria-busy','false');byId('more-topics').disabled=false;}}}
async function openThread(id,append=false){if(saving||append&&byId('more-replies').disabled)return;const version=++threadVersion,requestedOffset=append?replyOffset+50:0;byId('more-replies').disabled=true;if(!append){currentThread=null;replyOffset=0;byId('thread-content').replaceChildren();byId('thread-replies').replaceChildren();byId('reply-body').value='';notice('thread-title','Cargando conversación…');byId('reply-form').hidden=true;byId('more-replies').hidden=true;if(!byId('thread-dialog').open)byId('thread-dialog').showModal();}notice('reply-status','');try{
 const result=await api('posts/'+encodeURIComponent(id)+'?offset='+requestedOffset);if(version!==threadVersion||!byId('thread-dialog').open)return;replyOffset=requestedOffset;currentThread=result.post;notice('thread-title',result.post.title);if(!append){byId('thread-content').replaceChildren(postElement(result.post));byId('thread-title').focus();}for(const reply of result.replies)byId('thread-replies').append(postElement(reply));byId('more-replies').hidden=!result.hasMore;byId('reply-form').hidden=!account?.accepted_at||result.post.status!=='published';
 }catch(e){if(version===threadVersion){if(!append)notice('thread-title','No se ha podido abrir la conversación');notice('reply-status',e.message+(append?' Pulsa Más respuestas para reintentar.':''));}}finally{if(version===threadVersion)byId('more-replies').disabled=false;}}
for(const [id,value]of [['all-topics','all'],['my-topics','mine'],['moderation','moderation']])byId(id).addEventListener('click',()=>{if(saving)return;mode=value;for(const key of ['all-topics','my-topics','moderation'])byId(key).setAttribute('aria-pressed',String(key===id));loadTopics();});
byId('reload-topics').addEventListener('click',()=>{if(!saving)loadTopics();});byId('more-topics').addEventListener('click',()=>loadTopics(true));byId('more-replies').addEventListener('click',()=>{if(currentThread)return openThread(currentThread.id,true);});
byId('close-thread').addEventListener('click',()=>byId('thread-dialog').close());byId('thread-dialog').addEventListener('close',()=>{threadVersion++;currentThread=null;});
byId('profile-form').addEventListener('submit',async e=>{e.preventDefault();if(saving)return;const data={alias:byId('alias').value,accepted:byId('accept-rules').checked};locked(true);try{await api('profile',data);await loadAccount();notice('profile-status','Perfil guardado. Ya puedes enviar tu pregunta.');}catch(e){notice('profile-status',e.message);}finally{locked(false);}});
byId('topic-form').addEventListener('submit',async e=>{e.preventDefault();if(saving)return;const data={title:byId('topic-title').value,body:byId('topic-body').value,website:byId('website').value};locked(true);try{await api('posts',data);byId('topic-form').reset();notice('topic-status',account?.role==='owner'?'Pregunta publicada.':'Pregunta recibida. Aparecerá cuando Aleix la revise.');await loadTopics();}catch(e){notice('topic-status',e.message+' Tu texto sigue aquí.');}finally{locked(false);}});
byId('reply-form').addEventListener('submit',async e=>{e.preventDefault();if(saving||!currentThread)return;const id=currentThread.id,version=threadVersion,data={parentId:id,body:byId('reply-body').value};locked(true);try{const result=await api('posts',data);if(version!==threadVersion)return;byId('reply-body').value='';byId('thread-replies').append(postElement(result.post));notice('reply-status',account?.role==='owner'?'Respuesta publicada.':'Respuesta recibida. Solo tú y Aleix podéis verla mientras se revisa.');}catch(e){if(version===threadVersion)notice('reply-status',e.message+' Tu respuesta sigue aquí.');}finally{locked(false);}});
byId('logout').addEventListener('click',async()=>{if(saving)return;try{await api('logout',{});location.assign('/comunidad');}catch(e){notice('profile-status',e.message);}});
byId('link-owner').addEventListener('click',async()=>{if(saving||!confirm('¿Vincular esta cuenta de Google como dueño de la comunidad?'))return;locked(true);try{await api('owner',{});await loadAccount();notice('profile-status','Cuenta de dueño vinculada.');}catch(e){notice('profile-status',e.message);}finally{locked(false);}});
if(accessNotice)notice('community-status',accessNotice);
loadAccount().then(()=>loadTopics()).catch(e=>{notice('login-note',e.message);notice('community-status',(accessNotice?accessNotice+' ':'')+'No se ha podido cargar la comunidad. Usa Actualizar para reintentar.');byId('topics').setAttribute('aria-busy','false');});
})();
